// Handheld power index — record JAH-GGNS-HANDHELDCONSOLE-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"tflops": 3.5, "battery_h": 6, "price_usd": 550};
var value = (m.tflops*m.battery_h/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GGNS-HANDHELDCONSOLE-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GGNS-HANDHELDCONSOLE-000001|' + value.toFixed(2) + ' power index');

